#!/usr/bin/env python3
"""Test script to verify missing filters are implemented."""

import sys

def test_import():
    """Test that jinja2 can be imported without errors."""
    try:
        from jinja2 import Environment
        print("✓ Jinja2 imported successfully")
        return True
    except NameError as e:
        print(f"✗ Import failed with NameError: {e}")
        return False
    except Exception as e:
        print(f"✗ Import failed with {type(e).__name__}: {e}")
        return False

def test_filters_exist():
    """Test that all required filters exist in the FILTERS dictionary."""
    from jinja2.filters import FILTERS

    required_filters = [
        'upper', 'lower', 'capitalize', 'title',
        'sort', 'dictsort', 'items', 'xmlattr'
    ]

    all_exist = True
    for filter_name in required_filters:
        if filter_name in FILTERS:
            print(f"✓ Filter '{filter_name}' exists")
        else:
            print(f"✗ Filter '{filter_name}' is missing")
            all_exist = False

    return all_exist

def test_filter_functionality():
    """Test that filters work correctly."""
    from jinja2 import Environment

    env = Environment()

    # Test string filters
    tests = [
        ('upper', {'value': 'hello'}, 'HELLO'),
        ('lower', {'value': 'HELLO'}, 'hello'),
        ('capitalize', {'value': 'hello world'}, 'Hello world'),
        ('title', {'value': 'hello world'}, 'Hello World'),
    ]

