                all_pass = False
        except Exception as e:
            print(f"✗ Filter '{filter_name}' failed: {e}")
            all_pass = False

    # Test data organization filters
    data_tests = [
        ('sort', {'value': [3, 1, 2]}, [1, 2, 3]),
        ('dictsort', {'value': {'b': 2, 'a': 1}}, [('a', 1), ('b', 2)]),
    ]

    for filter_name, context, expected in data_tests:
        try:
            template = env.from_string(f"{{{{{context['value']}|{filter_name}}}}}")
            result = template.render()
            if result == str(expected):
                print(f"✓ Filter '{filter_name}' works correctly: {result}")
            else:
                print(f"✗ Filter '{filter_name}' returned wrong result: {result} (expected {expected})")
                all_pass = False
        except Exception as e:
            print(f"✗ Filter '{filter_name}' failed: {e}")
            all_pass = False

    # Test xmlattr filter
