        template = env.from_string("{{ {'foo': 'bar', 'baz': 'qux'}|xmlattr }}")
        result = template.render()
        if 'foo="bar"' in result and 'baz="qux"' in result:
            print(f"✓ Filter 'xmlattr' works correctly: {result}")
        else:
            print(f"✗ Filter 'xmlattr' returned wrong result: {result}")
            all_pass = False
    except Exception as e:
        print(f"✗ Filter 'xmlattr' failed: {e}")
        all_pass = False

    return all_pass

if __name__ == '__main__':
