class ImageScale(BrowserView):
    """BrowserView for individual image scale instances."""

    def __init__(self, context, request, data=None, fieldname=None,
                 width=None, height=None, uid=None, srcset=None):
        super(ImageScale, self).__init__(context, request)
        self.data = data
        self.fieldname = fieldname
        self.width = width
        self.height = height
        self.uid = uid
        self.srcset = srcset or []

    @property
    def url(self):
        return self.absolute_url()

    def absolute_url(self):
        """Return the scale's URL."""
        if self.uid:
            # UID-based URL
            return "{0}/@@images/{1}.{2}".format(
                self.context.absolute_url(),
                self.uid,
                self.mimetype.split("/")[-1],
            )
        else:
            # Field-based URL
            return "{0}/@@images/{1}".format(
                self.context.absolute_url(),
                self.fieldname,
            )

    @property
    def mimetype(self):
