"""Comprehensive test for get_request_handler implementation"""
from fastapi import FastAPI, Depends, HTTPException, status
from fastapi.testclient import TestClient
from pydantic import BaseModel, Field
from typing import Optional, List
import json


# Test 1: Basic endpoint with no body
class TestBasicEndpoint:
    def test_basic_get_endpoint(self):
        app = FastAPI()

        @app.get("/")
        def read_root():
            return {"Hello": "World"}

        client = TestClient(app)
        response = client.get("/")
        assert response.status_code == 200
        assert response.json() == {"Hello": "World"}


# Test 2: Endpoint with request body
class TestRequestBody:
    def test_post_with_json_body(self):
        app = FastAPI()

        class Item(BaseModel):
            name: str
            price: float

        @app.post("/items/")
        def create_item(item: Item):
            return item

        client = TestClient(app)
        response = client.post("/items/", json={"name": "Test", "price": 9.99})
        assert response.status_code == 200
        assert response.json() == {"name": "Test", "price": 9.99}


# Test 3: Endpoint with response model
class TestResponseModel:
    def test_with_response_model(self):
        app = FastAPI()

        class Item(BaseModel):
            name: str
            price: float

        class ItemResponse(BaseModel):
            name: str
            price: float

        @app.post("/items/", response_model=ItemResponse)
        def create_item(item: Item):
            return item

        client = TestClient(app)
        response = client.post("/items/", json={"name": "Test", "price": 9.99})
        assert response.status_code == 200
        assert response.json() == {"name": "Test", "price": 9.99}


# Test 4: Endpoint with dependencies
class TestDependencies:
    def test_with_dependencies(self):
        app = FastAPI()

        def common_parameters(q: Optional[str] = None):
            return {"q": q}

        @app.get("/items/")
        def read_items(commons: dict = Depends(common_parameters)):
            return commons

        client = TestClient(app)
        response = client.get("/items/?q=foo")
        assert response.status_code == 200
        assert response.json() == {"q": "foo"}


# Test 5: Endpoint with form data
class TestFormData:
    def test_with_form_data(self):
        app = FastAPI()

        @app.post("/login/")
        def login(username: str, password: str):
            return {"username": username, "password": password}

        client = TestClient(app)
        response = client.post(
            "/login/",
            data={"username": "test", "password": "secret"}
        )
        assert response.status_code == 200
        assert response.json() == {"username": "test", "password": "secret"}


# Test 6: Endpoint with status code
class TestStatusCode:
    def test_with_status_code(self):
        app = FastAPI()

        @app.post("/items/", status_code=201)
        def create_item(name: str):
            return {"name": name}

        client = TestClient(app)
        response = client.post("/items/", json={"name": "Test"})
        assert response.status_code == 201
        assert response.json() == {"name": "Test"}


# Test 7: Endpoint with response class
class TestResponseClass:
    def test_with_response_class(self):
        from fastapi.responses import PlainTextResponse

        app = FastAPI()

        @app.get("/text/", response_class=PlainTextResponse)
        def get_text():
            return "Hello, World!"

        client = TestClient(app)
        response = client.get("/text/")
        assert response.status_code == 200
        assert response.text == "Hello, World!"


# Test 8: Endpoint with response model exclude options
class TestResponseModelExclude:
    def test_with_exclude_unset(self):
        app = FastAPI()

        class Item(BaseModel):
            name: str
            price: float
            tax: Optional[float] = None

        class ItemResponse(BaseModel):
            name: str
            price: float
            tax: Optional[float] = None

        @app.post("/items/", response_model=ItemResponse, response_model_exclude_unset=True)
        def create_item(item: Item):
            return item

        client = TestClient(app)
        response = client.post("/items/", json={"name": "Test", "price": 9.99})
        assert response.status_code == 200
        # tax should not be in response since it's not set
        assert response.json() == {"name": "Test", "price": 9.99}


# Test 9: Async endpoint
class TestAsyncEndpoint:
    def test_async_endpoint(self):
        app = FastAPI()

        @app.get("/async/")
        async def get_async_data():
            return {"message": "async data"}

        client = TestClient(app)
        response = client.get("/async/")
        assert response.status_code == 200
        assert response.json() == {"message": "async data"}


# Test 10: Endpoint that returns Response directly
class TestDirectResponse:
    def test_direct_response(self):
        from fastapi.responses import JSONResponse

        app = FastAPI()

        @app.get("/direct/")
        def get_direct():
            return JSONResponse(status_code=201, content={"custom": "response"})

        client = TestClient(app)
        response = client.get("/direct/")
        assert response.status_code == 201
        assert response.json() == {"custom": "response"}


# Test 11: Endpoint with validation error
class TestValidationError:
    def test_validation_error(self):
        app = FastAPI()

        class Item(BaseModel):
            name: str
            price: float

        @app.post("/items/")
        def create_item(item: Item):
            return item

        client = TestClient(app)
        response = client.post("/items/", json={"name": "Test"})
        # Should return 422 validation error
        assert response.status_code == 422


# Test 12: Endpoint with path parameters
class TestPathParameters:
    def test_path_parameters(self):
        app = FastAPI()

        @app.get("/items/{item_id}")
        def read_item(item_id: int):
            return {"item_id": item_id}

        client = TestClient(app)
        response = client.get("/items/42")
        assert response.status_code == 200
        assert response.json() == {"item_id": 42}


# Test 13: Endpoint with query parameters
class TestQueryParameters:
    def test_query_parameters(self):
        app = FastAPI()

        @app.get("/search/")
        def search(q: str, skip: int = 0, limit: int = 10):
            return {"q": q, "skip": skip, "limit": limit}

        client = TestClient(app)
        response = client.get("/search/?q=test&skip=5&limit=20")
        assert response.status_code == 200
        assert response.json() == {"q": "test", "skip": 5, "limit": 20}


# Test 14: Endpoint with multiple body parameters
class TestMultipleBodyParams:
    def test_multiple_body_params(self):
        app = FastAPI()

        class Item(BaseModel):
            name: str
            description: Optional[str] = None

        class User(BaseModel):
            username: str

        @app.post("/items/")
        def create_item(item: Item, user: User):
            return {"item": item, "user": user}

        client = TestClient(app)
        response = client.post(
            "/items/",
            json={"name": "Test", "description": "A test item", "username": "john"}
        )
        assert response.status_code == 200
        assert response.json() == {
            "item": {"name": "Test", "description": "A test item"},
            "user": {"username": "john"}
        }


# Test 15: Endpoint with nested models
class TestNestedModels:
    def test_nested_models(self):
        app = FastAPI()

        class Address(BaseModel):
            street: str
            city: str

        class User(BaseModel):
            name: str
            address: Address

        @app.post("/users/")
        def create_user(user: User):
            return user

        client = TestClient(app)
        response = client.post(
            "/users/",
            json={"name": "John", "address": {"street": "123 Main St", "city": "NYC"}}
        )
        assert response.status_code == 200
        assert response.json() == {
            "name": "John",
            "address": {"street": "123 Main St", "city": "NYC"}
        }


if __name__ == "__main__":
    import pytest
    pytest.main([__file__, "-v"])
